package io.agora.media; import java.nio.*; import java.util.*; public class ByteBuf { ByteBuffer buffer = ByteBuffer.allocate(1024).order(ByteOrder.LITTLE_ENDIAN); public ByteBuf(){} public ByteBuf(byte[] bytes){ this.buffer=ByteBuffer.wrap(bytes).order(ByteOrder.LITTLE_ENDIAN);} public byte[] asBytes(){ byte[] out = new byte[buffer.position()]; buffer.rewind(); buffer.get(out,0,out.length); return out;} public ByteBuf put(short v){ buffer.putShort(v); return this;} public ByteBuf put(byte[] v){ put((short)v.length); buffer.put(v); return this;} public ByteBuf put(int v){ buffer.putInt(v); return this;} public ByteBuf put(String v){ return put(v.getBytes());} public ByteBuf putIntMap(TreeMap extra){ put((short)extra.size()); for(Object o:extra.entrySet()){ Map.Entry pair=(Map.Entry)o; put((short)pair.getKey()); put((int)pair.getValue()); } return this;} }
